def lay_sach_truoc_cung(danh_sach):
    # Kiểm tra nếu ngăn xếp rỗng
    if not danh_sach:
        return (None, [])

    # Tạo bản sao của danh sách để tránh thay đổi danh sách gốc
    stack = danh_sach[:]
    # Lấy phần tử cuối cùng ra (đỉnh stack)
    top_stack = stack[-1]

    # Lấy lần lượt từng phần tử từ đỉnh stack ra
    for i in range(len(stack) - 1, -1, -1):
        stack.pop()

    return (stack, top_stack)
