def kiem_tra_ket_noi(do_thi, start, end):
    # Tập hợp lưu trữ các nút đã được thăm để tránh lặp vô hạn
    visited = set()

    def dfs(current_node):
        # Nếu tìm thấy nút đích, trả về True
        if current_node == end:
            return True

        # Đánh dấu nút hiện tại đã thăm
        visited.add(current_node)

        # Duyệt qua các nút kề của nút hiện tại
        for neighbor in do_thi.get(current_node, []):
            if neighbor not in visited:
                if dfs(neighbor):
                    return True
        return False

    return dfs(start)
